begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','donors','donors exists');
select has_table('public','donations','donations exists');
select has_table('public','sponsorships','sponsorships exists');
select has_table('public','sponsorship_payments','sponsorship_payments exists');
insert into auth.users(id) select ('a3000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,3)n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('a4000000-0000-0000-0000-00000000000'||n)::uuid,('a3000000-0000-0000-0000-00000000000'||n)::uuid,now(),now() from generate_series(1,3)n;
insert into public.employees(id,employee_code,display_name) select ('a5000000-0000-0000-0000-00000000000'||n)::uuid,'DONATION'||n,'Synthetic' from generate_series(1,3)n;
insert into private.employee_auth select ('a5000000-0000-0000-0000-00000000000'||n)::uuid,('a3000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,3)n;
insert into public.employee_permissions(employee_id,donations_write,donations_read,cases_write) values
 ('a5000000-0000-0000-0000-000000000001',true,false,false),('a5000000-0000-0000-0000-000000000002',false,true,false),('a5000000-0000-0000-0000-000000000003',false,false,true);
insert into public.families(id,name) values('a6000000-0000-0000-0000-000000000001','أسرة وهمية');
select set_config('request.jwt.claims','{"sub":"a3000000-0000-0000-0000-000000000001","session_id":"a4000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$insert into public.donors(id,name,phone) values('a7000000-0000-0000-0000-000000000001','متبرع وهمي','01000000000')$$,'donation-only writer creates donor');
select is((select count(*)::int from public.families),0,'donation permission does not expose family table');
select throws_ok($$insert into public.sponsorships(donor_id,family_id,monthly_amount,start_date) values('a7000000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000001',350,'2024-01-31')$$,'42501',null,'donation-only writer cannot link family');
reset role;
update public.employee_permissions set cases_read=true where employee_id='a5000000-0000-0000-0000-000000000001';
set local role authenticated;
select lives_ok($$insert into public.donations(donor_id,donation_type,kind,amount,received_on) select 'a7000000-0000-0000-0000-000000000001',t,'cash',100,'2026-01-01' from unnest(array['cash','in_kind_food','clothing','medicine','zakat','sadaqa','zakat_al_fitr','ramadan_food_bags','eid_clothing','sacrificial_meat','blankets','school_supplies','treatment_support'])t$$,'all thirteen donation types accepted');
select lives_ok($$insert into public.donations(donor_id,donation_type,kind,quantity,unit,description,received_on) values('a7000000-0000-0000-0000-000000000001','ramadan_food_bags','in_kind',10,'شنطة','أرز وزيت','2026-01-01')$$,'in-kind quantity and description supported');
select throws_ok($$insert into public.donations(donation_type,kind,amount,received_on) values('unknown','cash',100,'2026-01-01')$$,'23514',null,'unknown type rejected');
select throws_ok($$insert into public.donations(donation_type,kind,amount,received_on) values('cash','cash',0,'2026-01-01')$$,'23514',null,'zero cash rejected');
select throws_ok($$insert into public.donations(donation_type,kind,quantity,unit,description,received_on) values('clothing','in_kind',1,'قطعة','','2026-01-01')$$,'23514',null,'in-kind requires description');
select throws_ok($$insert into public.donations(donation_type,kind,amount,received_on) values('cash','cash','NaN','2026-01-01')$$,'23514',null,'non-finite cash rejected');
select throws_ok($$insert into public.donations(donation_type,kind,amount,currency,received_on) values('cash','cash',1,'USD','2026-01-01')$$,'23514',null,'EGP only');
select lives_ok($$insert into public.sponsorships(id,donor_id,family_id,monthly_amount,start_date) values('a8000000-0000-0000-0000-000000000001','a7000000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000001',350,'2024-01-31')$$,'writer links donor and family');
select lives_ok($$select public.generate_sponsorship_installments('2024-01-30')$$,'cutoff before start');
select is((select count(*)::int from public.sponsorship_payments),0,'no installment before start');
select lives_ok($$select public.generate_sponsorship_installments('2024-01-31')$$,'inclusive cutoff');
select is((select count(*)::int from public.sponsorship_payments),1,'installment on cutoff included');
select is(public.sponsorship_due_date('2025-01-31','2025-02-01'),'2025-02-28'::date,'non-leap February clamps to 28');
select lives_ok($$select public.generate_sponsorship_installments('2024-03-31')$$,'generate through inclusive date');
select is((select string_agg(due_date::text,',' order by due_date) from public.sponsorship_payments),'2024-01-31,2024-02-29,2024-03-31','monthly day clamps to leap-month last day');
select lives_ok($$select public.generate_sponsorship_installments('2024-03-31')$$,'generation is idempotent');
select is((select count(*)::int from public.sponsorship_payments),3,'no duplicates');
select throws_ok($$insert into public.sponsorship_payments(sponsorship_id,installment_month,due_date,amount_due) values('a8000000-0000-0000-0000-000000000001','2024-01-01','2024-01-31',350)$$,'23505',null,'unique sponsorship/month');
select throws_ok($$insert into public.sponsorship_payments(sponsorship_id,installment_month,due_date,amount_due) values('a8000000-0000-0000-0000-000000000001','2024-04-01','2024-04-01',350)$$,'23514',null,'forged monthly due date rejected');
select lives_ok($$update public.sponsorship_payments set received_on='2024-02-10',amount_received=350 where installment_month='2024-01-01'$$,'record late receipt');
select throws_ok($$update public.sponsorship_payments set received_on=null,amount_received=null where installment_month='2024-01-01'$$,'23514',null,'recorded receipt cannot be cleared');
select throws_ok($$update public.sponsorship_payments set received_on='2024-02-11' where installment_month='2024-01-01'$$,'23514',null,'recorded receipt date cannot be changed');
select throws_ok($$update public.sponsorship_payments set amount_received=351 where installment_month='2024-01-01'$$,'23514',null,'recorded receipt amount cannot be changed');
select throws_ok($$update public.sponsorship_payments set received_on='2024-02-10' where installment_month='2024-02-01'$$,'23514',null,'receipt date and amount must be paired');
select lives_ok($$update public.sponsorships set end_date='2024-02-29'$$,'inclusive end date');
select lives_ok($$select public.generate_sponsorship_installments('2024-12-31')$$,'ended sponsorship stops generation');
select is((select count(*)::int from public.sponsorship_payments),2,'unpaid installments after end removed; inclusive end installment retained');
select throws_ok($$update public.sponsorships set end_date='2024-01-30'$$,'23514',null,'end before start rejected');
select throws_ok($$update public.sponsorships set start_date='2024-01-30'$$,'23514',null,'schedule history cannot be rewritten');
select lives_ok($$update public.sponsorship_payments set received_on='2024-03-10',amount_received=350 where installment_month='2024-02-01'$$,'receive February');
select throws_ok($$update public.sponsorships set end_date='2024-01-31'$$,'23514',null,'end cannot erase received history');
reset role;
insert into public.sponsorships(id,donor_id,family_id,monthly_amount,start_date) values('a8000000-0000-0000-0000-000000000002','a7000000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000001',450,'2024-01-31');
select set_config('request.jwt.claims','{"sub":"a3000000-0000-0000-0000-000000000002","session_id":"a4000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.sponsorships),0,'donation-only reader cannot see family IDs');
select throws_ok($$select public.generate_sponsorship_installments('2024-12-31')$$,'42501',null,'donation-only reader cannot materialize family-linked schedule');
reset role;
update public.employee_permissions set cases_read=true where employee_id='a5000000-0000-0000-0000-000000000002';
set local role authenticated;
select is((select count(*)::int from public.donations),14,'reader sees real donations');
select is((select count(*)::int from public.donors),1,'reader sees donors');
select is((select count(*)::int from public.sponsorships),2,'reader sees sponsorships');
select is((select count(*)::int from public.sponsorship_payments),2,'reader sees payments');
select throws_ok($$insert into public.donors(name) values('denied')$$,'42501',null,'reader cannot insert donor');
select throws_ok($$insert into public.donations(donation_type,kind,amount,received_on) values('cash','cash',10,'2026-01-01')$$,'42501',null,'reader cannot insert donation');
select throws_ok($$insert into public.sponsorships(donor_id,family_id,monthly_amount,start_date) values('a7000000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000001',10,'2026-01-01')$$,'42501',null,'reader cannot insert sponsorship');
select lives_ok($$select public.generate_sponsorship_installments('2024-01-31')$$,'reader materializes January without writer activity');
select is((select count(*)::int from public.sponsorship_payments where sponsorship_id='a8000000-0000-0000-0000-000000000002'),1,'reader sees January expected installment');
select lives_ok($$select public.generate_sponsorship_installments('2024-02-29')$$,'reader crosses month boundary without writer activity');
select is((select string_agg(due_date::text,',' order by due_date) from public.sponsorship_payments where sponsorship_id='a8000000-0000-0000-0000-000000000002'),'2024-01-31,2024-02-29','reader sees current and overdue obligations');
select ok((select bool_and(amount_due=450 and received_on is null and amount_received is null) from public.sponsorship_payments where sponsorship_id='a8000000-0000-0000-0000-000000000002'),'reader generation creates unpaid expected amounts only');
select throws_ok($$select public.generate_sponsorship_installments('2099-01-31')$$,'23514',null,'reader cannot create installments beyond current UTC month');
select throws_ok($$insert into public.sponsorship_payments(sponsorship_id,installment_month,due_date,amount_due) values('a8000000-0000-0000-0000-000000000002','2024-03-01','2024-03-31',450)$$,'42501',null,'reader cannot insert arbitrary payment rows');
with changed as (update public.sponsorships set end_date='2024-01-31' returning id) select is(count(*)::int,0,'reader cannot change schedule through generation permission') from changed;
with changed as (update public.sponsorship_payments set amount_due=999 returning id) select is(count(*)::int,0,'reader cannot change expected amounts') from changed;
with changed as (update public.sponsorship_payments set amount_received=999,received_on='2024-02-02' returning id) select is(count(*)::int,0,'reader cannot mark received') from changed;
reset role;
select set_config('request.jwt.claims','{"sub":"a3000000-0000-0000-0000-000000000003","session_id":"a4000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select (select count(*) from public.donors)+(select count(*) from public.donations)+(select count(*) from public.sponsorships)+(select count(*) from public.sponsorship_payments))::int,0,'cases-only sees no donation data');
select throws_ok($$insert into public.donors(name) values('denied')$$,'42501',null,'cases-only cannot create donor');
select throws_ok($$insert into public.donations(donation_type,kind,amount,received_on) values('cash','cash',10,'2026-01-01')$$,'42501',null,'cases-only cannot create donation');
select throws_ok($$insert into public.sponsorships(donor_id,family_id,monthly_amount,start_date) values('a7000000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000001',10,'2026-01-01')$$,'42501',null,'cases-only cannot create sponsorship');
select throws_ok($$insert into public.sponsorship_payments(sponsorship_id,installment_month,due_date,amount_due) values('a8000000-0000-0000-0000-000000000001','2024-02-01','2024-02-29',350)$$,'42501',null,'cases-only cannot insert payment');
with changed as (update public.donors set name='denied' returning id) select is(count(*)::int,0,'cases-only cannot update donors') from changed;
with changed as (update public.donations set amount=999 returning id) select is(count(*)::int,0,'cases-only cannot update donations') from changed;
with changed as (update public.sponsorships set end_date='2024-01-31' returning id) select is(count(*)::int,0,'cases-only cannot update sponsorships') from changed;
with changed as (update public.sponsorship_payments set amount_received=999 returning id) select is(count(*)::int,0,'cases-only cannot update payments') from changed;
reset role;
update auth.sessions set created_at=now()-interval '31 days' where id='a4000000-0000-0000-0000-000000000001';
select set_config('request.jwt.claims','{"sub":"a3000000-0000-0000-0000-000000000001","session_id":"a4000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.donors),0,'expired writer cannot read donors');
select throws_ok($$select public.generate_sponsorship_installments('2024-12-31')$$,'42501',null,'expired writer cannot generate');
reset role;
set local role anon;
select throws_ok($$select * from public.donors$$,'42501',null,'anonymous donor read denied');
select throws_ok($$select * from public.donations$$,'42501',null,'anonymous donation read denied');
select throws_ok($$select * from public.sponsorships$$,'42501',null,'anonymous sponsorship read denied');
select throws_ok($$select * from public.sponsorship_payments$$,'42501',null,'anonymous payment read denied');
select * from finish(); rollback;
